attribute vec4 color4;\n attribute vec4:
attribute vec4 color4;
  attribute vec4 dyn4; // Four ParticleModuleParameterDynamic channels (read by procedural smoke only)
  varying vec2 vUv;
  varying vec4 vCol;
  varying vec4 vDyn;
  varying float vViewZ; // View-space depth in meters for smoke fading near the camera
  void main() {
    vUv = uv;
    vCol = color4;
    vDyn = dyn4;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    vViewZ = -mv.z;
    gl_Position = projectionMatrix * mv;
  }

uniform sampler2D map;\n uniform sample:
uniform sampler2D map;
  uniform sampler2D lut;
  uniform float lutMin, lutMix, emissiveMult, lutVariant, nLuts, errorFix;
  uniform bool rot90, useLut, useAlpha, texColor, particleColor;
  varying vec2 vUv;
  varying vec4 vCol;
  void main() {
    vec2 uv = rot90 ? vec2(1.0 - vUv.y, vUv.x) : vUv;
    vec4 t = texture2D(map, uv);
    float op = useAlpha ? t.a : t.g;
    vec3 e;
    if (texColor) e = t.rgb * emissiveMult;
    else {
      vec3 c;
      if (useLut) {
        float k = mix(lutMin, lutMix, t.g);
        vec2 luv = mix(vec2(k, (k + lutVariant) / nLuts), vec2((lutVariant + 0.5) / nLuts), errorFix);
        c = texture2D(lut, luv).rgb;
      } else c = vec3(t.g);
      e = c * emissiveMult;
      if (particleColor) e *= vCol.rgb;
    }
    float a = clamp(op * vCol.a, 0.0, 1.0);
    gl_FragColor = vec4(max(e, vec3(0.0)) * a, a); // Linear, premultiplied
  }

uniform sampler2D mapE;\n uniform sampl:
uniform sampler2D mapE;
  uniform sampler2D mapO;
  uniform float gameTime;
  uniform vec4 pE;  // rot, rate, -, -
  uniform vec4 pE2; // scale.xy, offset.xy
  uniform vec4 pO;  // rot, rate, scrollU, scrollV
  uniform vec4 pO2; // scale.xy, offset.xy
  uniform vec4 pO1; // rot, rate, scrollU, scrollV
  uniform vec4 pO12;// scale.xy, offset.xy
  uniform vec3 pFade; // 1/radius (per cm), 1/(1-hardness), 1/soft-particle distance (per cm)
  varying vec2 vUv;
  varying vec4 vCol;
  varying float vViewZ;
  vec2 rot(vec2 q, float turns) {
    float a = turns * 6.28, s = sin(a), c = cos(a);
    return vec2(c * q.x - s * q.y, s * q.x + c * q.y);
  }
  void main() {
    vec2 p = vUv * 4.0 - 2.0;
    vec2 q = vec2(fract(atan(p.y, p.x) * 0.159155), length(p)) - 0.5;
    vec2 gx = dFdx(vUv), gy = dFdy(vUv);
    float t = gameTime;
    vec2 uvE = (rot(q, pE.y * t + pE.x) + 0.5) * pE2.xy + pE2.zw;
    float e = textureGrad(mapE, uvE, gx, gy).r;
    vec2 uvA = (rot(q, pO.y * t + pO.x) + 0.5) * pO2.xy + pO2.zw;
    uvA = vec2(uvA.x + pO.z * t, clamp(uvA.y + pO.w * t, 0.01, 0.99));
    float a = textureGrad(mapO, uvA, gx, gy).r * vCol.a;
    vec2 uvB = (rot(q, pO1.y * t + pO1.x) + 0.5) * pO12.xy + pO12.zw;
    uvB = vec2(uvB.x + pO1.z * t, clamp(uvB.y + pO1.w * t, 0.01, 0.99));
    float b = textureGrad(mapO, uvB, gx, gy).r;
    float pix = vViewZ * 100.0; // centimeters
    float camFade = 1.0 - clamp((1.0 - abs(pix) * pFade.x) * pFade.y, 0.0, 1.0);
    float op = clamp(camFade * a * b, 0.0, 1.0);
    gl_FragColor = vec4(e * vCol.rgb * op, op);
  }

uniform sampler2D mapE;
  uniform sampler2D mapO;
  uniform float gameTime;
  uniform vec4 pE;  // rot, rate, scrollU, scrollV
  uniform vec4 pE2; // scale.xy, offset.xy
  uniform vec4 pO;  // rot, rate, scrollU, scrollV
  uniform vec4 pO2; // scale.xy, offset.xy
  uniform vec3 pFade; // 1/radius (per cm), 1/(1-hardness), 1/soft-particle distance (per cm)
  uniform vec3 pK;    // AlphaPower, Alpha_ColorMult, EmissivePower
  uniform vec3 emisCol;
  varying vec2 vUv;
  varying vec4 vCol;
  varying float vViewZ;
  vec2 rot(vec2 q, float turns) {
    float a = turns * 6.28, s = sin(a), c = cos(a);
    return vec2(c * q.x - s * q.y, s * q.x + c * q.y);
  }
  float pw(float x, float k) { return x <= 0.0 ? 0.0 : pow(x, k); }
  void main() {
    float t = gameTime;
    vec2 d = vUv - 0.5;
    vec2 uvA = (rot(d, pO.y * t + pO.x) + 0.5) * pO2.xy + pO2.zw + pO.zw * t;
    float a = pw(texture2D(mapO, uvA).r, pK.x);
    vec2 uvE = (rot(d, pE.y * t + pE.x) + 0.5) * pE2.xy + pE2.zw + pE.zw * t;
    vec4 e = texture2D(mapE, uvE);
    float pix = vViewZ * 100.0; // centimeters
    float camFade = 1.0 - clamp((1.0 - abs(pix) * pFade.x) * pFade.y, 0.0, 1.0);
    float op = clamp(a * e.a * pK.y * vCol.a * camFade, 0.0, 1.0);
    vec3 c = vec3(pw(e.r, pK.z), pw(e.g, pK.z), pw(e.b, pK.z)) * emisCol * vCol.rgb;
    gl_FragColor = vec4(max(c, vec3(0.0)) * op, op);
  }

uniform sampler2D map;\n uniform float:
uniform sampler2D map;
  uniform float gameTime;
  uniform vec4 pA; // Pan_X, Pan_Y, Scale_X, Scale_Y
  uniform vec4 pB; // Distortion_Strength, 1/max(Distort_Radus,1e-5), Distortion_Speed, Edge_Distortion
  uniform vec4 pC; // TempRadius, Temp, Tex_Power, Erosion
  uniform vec4 pD; // 1/max(Edge_Radius,1e-5), 1/max(1−Edge_Hardness,1e-5), 1/max(DepthFade_Dist,1e-5)(per centimeter), fake lighting
  uniform vec3 tint; // Color.rgb × Color.a
  varying vec2 vUv;
  varying vec4 vCol;
  varying vec4 vDyn;
  // UE BlackBody, excluding the intensity term
  vec3 blackbody(float T) {
    float T2 = T * T;
    float u = (0.860117757 + 1.54118254e-4 * T + 1.28641212e-7 * T2) / (1.0 + 8.42420235e-4 * T + 7.08145163e-7 * T2);
    float v = (0.317398726 + 4.22806245e-5 * T + 4.20481691e-8 * T2) / (1.0 - 2.89741816e-5 * T + 1.61456053e-7 * T2);
    float den = 2.0 * u - 8.0 * v + 4.0;
    float x = 3.0 * u / den, y = 2.0 * v / den;
    vec3 XYZ = vec3(x / y, 1.0, (1.0 - x - y) / y);
    return vec3(dot(vec3(3.2404542, -1.5371385, -0.4985314), XYZ),
                dot(vec3(-0.9692660, 1.8760108, 0.0415560), XYZ),
                dot(vec3(0.0556434, -0.2040259, 1.0572252), XYZ));
  }
  void main() {
    vec2 uv = vUv;
    float t = gameTime;
    float dist = length(uv - 0.5);
    float m = clamp(1.0 - dist * pB.y, 0.0, 1.0);
    float s = vDyn.w * 0.4 + 0.5, sp = vDyn.w * 0.6 + 0.8, k = vDyn.w * 0.08 + 0.18;
    vec2 panYX = t * vec2(pA.y, pA.x), panXY = t * pA.xy;
    vec2 uvYX = vec2(uv.y * pA.w, uv.x * pA.z), uvXY = vec2(uv.x * pA.z, uv.y * pA.w);
    float speed = t * pB.z * sp;
    float lo = -0.2 * pB.x / s, hi = 0.2 * pB.x / s;
    vec2 n1 = texture2D(map, uvYX * s + panYX).xy;
    float baseA = mix(m, n1.x, 0.2) + speed * 0.25;
    float w = clamp((sin((baseA + 0.25) * 6.283185) + 0.75) * 0.75, 0.0, 1.0);
    vec2 P = mix(uvYX + 0.5, n1 + 0.5, mix(lo, hi, fract(baseA + 0.5)));
    float sA = texture2D(map, P * s + panYX).b;
    vec2 n2 = texture2D(map, uvXY * s + panXY).xy;
    float baseB = mix(m, n2.x, 0.2) + speed * 0.25;
    vec2 Q = uvXY + mix(lo, hi, fract(baseB)) * (n2 - uvXY);
    float sB = texture2D(map, Q * s + panXY).b;
    float noise = mix(sB, sA, w);
    if (noise <= 0.0) { gl_FragColor = vec4(0.0); return; }
    vec3 col = vCol.rgb * tint * pow(noise, pC.z);
    float fall = max(1.0 - dist / max(vDyn.z * pC.x, 1e-5), 0.0);
    float T = (1.0 - noise) * fall * fall * vDyn.y * pC.y;
    col += blackbody(T) * pow(T * 0.0004, 4.0);
    col *= pD.w;
    vec2 uv2 = uv + (k * pB.w) * (vec2(noise) - uv);
    float edge = clamp((1.0 - length(uv2 - 0.5) * pD.x) * pD.y, 0.0, 1.0);
    float op = clamp(edge * pow(noise, vDyn.x * pC.w) * vCol.a, 0.0, 1.0);
    gl_FragColor = vec4(max(col, vec3(0.0)) * op, op);
  }

uniform sampler2D map;\n uniform bool a:
uniform sampler2D map;
  uniform bool alphaFromLum, softCircle;
  varying vec2 vUv;
  varying vec4 vCol;
  void main() {
    vec4 t = texture2D(map, vUv);
    float g = clamp(dot(t.rgb, vec3(0.299, 0.587, 0.114)), 0.0, 1.0);
    float op = alphaFromLum ? g : t.a;
    // The original opaque tiled procedural cloud uses a gradient to form a blob; approximate it with a soft circle
    if (softCircle) op *= smoothstep(1.0, 0.25, length(vUv - 0.5) * 2.0);
    float a = clamp(op * vCol.a, 0.0, 1.0);
    // Use luminance only: procedural smoke has unrelated noise in each texture channel; reading it as color introduces green artifacts. Use particle color instead
    gl_FragColor = vec4(vec3(g) * vCol.rgb * a, a);
  }
